B.XS=new A.Y(B.r,["{r}! Aqui, aqui! Me tira dessa c\xe1psula... eu n\xe3o aguento ficar parada!","{r}! Over here, over here! Get me out of this capsule... I can't stand sitting still!","\xa1{r}! \xa1Aqu\xed, aqu\xed! S\xe1came de esta c\xe1psula... \xa1no aguanto quedarme quieta!"],t.w)
B.XL=new A.Y(B.r,["Ei, {r}! Me tira daqui! Meu canh\xe3o t\xe1 doido pra explodir essa c\xe1psula!","Hey, {r}! Get me out! My cannon is dying to blast this capsule!","\xa1Oye, {r}! \xa1S\xe1came de aqu\xed! \xa1Mi ca\xf1\xf3n se muere por volar esta c\xe1psula!"],t.w)
B.Xv=new A.Y(B.r,["{r}?! Ufa, finalmente! R\xe1pido, antes que os rob\xf4s voltem... eu ouvi eles!","{r}?! Phew, finally! Hurry, before the robots come back... I heard them!","\xbf\xa1{r}!? \xa1Uf, por fin! R\xe1pido, antes de que vuelvan los robots... \xa1los o\xed!"],t.w)
B.X7=new A.Y(B.r,["{r}... senti sua energia. Essa c\xe1psula bloqueia meus poderes. Preciso de voc\xea.","{r}... I felt your energy. This capsule blocks my powers. I need you.","{r}... sent\xed tu energ\xeda. Esta c\xe1psula bloquea mis poderes. Te necesito."],t.w)
B.WN=new A.Y(B.j2,[B.XS,B.XL,B.Xv,B.X7],t.vb)
B.iV=new A.Y(B.j2,[2,3,5,8],t.eL)
B.XI=new A.Y(B.r,["Livre! Valeu, Kael! Agora ningu\xe9m me segura... bora atr\xe1s desses chefes!","Free! Thanks, Kael! Now nobody can stop me... let's go after those bosses!","\xa1Libre! \xa1Gracias, Kael! Ahora nadie me detiene... \xa1vamos por esos jefes!"],t.w)
B.X5=new A.Y(B.r,["At\xe9 que enfim! Agora sim... BUM! Bora derrubar uns chefes!","Finally! Now we're talking... BOOM! Let's take down some bosses!","\xa1Por fin! Ahora s\xed... \xa1BUM! \xa1Vamos a derribar unos jefes!"],t.w)
B.WY=new A.Y(B.r,["Eu avisei que ia dar errado, n\xe3o avisei? Valeu, parceiro. Minha mira \xe9 sua!","I told you it would go wrong, didn't I? Thanks, partner. My aim is yours!","Te dije que saldr\xeda mal, \xbfo no? Gracias, compa\xf1ero. \xa1Mi punter\xeda es tuya!"],t.w)
B.XH=new A.Y(B.r,["Minha energia voltou... obrigado. Juntos, nada vai nos parar.","My energy is back... thank you. Together, nothing can stop us.","Mi energ\xeda volvi\xf3... gracias. Juntos, nada nos detendr\xe1."],t.w)
B.WO=new A.Y(B.j2,[B.XI,B.X5,B.WY,B.XH],t.vb)
B.Y1=new A.Y(B.r,["Segure PULAR na queda para planar!","Hold JUMP while falling to glide!","\xa1Mant\xe9n SALTAR al caer para planear!"],t.w)
B.Xz=new A.Y(B.r,["DASH arrebenta os muros de a\xe7o!","DASH smashes the steel walls!","\xa1DASH rompe los muros de acero!"],t.w)
B.Y7=new A.Y(B.r,["O casco de cristal aguenta espinhos!","The crystal hull shrugs off spikes!","\xa1El casco de cristal aguanta las p\xfaas!"],t.w)
B.WP=new A.cL([B.mm,B.Y1,B.mk,B.Xz,B.ml,B.Y7],A.au("cL<ii,be<u,u>>"))
